        this.nodes=(copy.nodes||[]).map((node,index)=>({...node,type:String(node.type||node.data?.type||'test-suite').replace(/_/g,'-'),data:node.data||{},position:node.position||{x:node.x||100+index*350,y:node.y||100}}));
